import { readSourcePresentation } from '../storage/library/sourcePresentation';
import fs from 'fs/promises';
import fsSync from 'fs';
import path from 'path';
import { createHash } from 'crypto';
import { z } from 'zod';
import {
  isPathStrictlyInsideRoot,
  isPathWithinRoot,
} from '../utils/pathContainment';
import type { VariantHistoryManifest } from '../services/VariantHistoryService';

const HISTORY_DIRECTORIES = [
  'variants',
  'variant-context',
  'store.git',
] as const;
const SNAPSHOT_TOP_LEVEL = new Set([
  'HEAD',
  'config',
  'objects',
  'refs',
  'packed-refs',
]);
const SafeId = z.string().regex(/^[A-Za-z0-9_-]+$/);
const Pointer = z
  .object({ ref: z.string(), commitSha: z.string().regex(/^[a-f0-9]{40}$/) })
  .passthrough();
const ManifestSchema = z
  .object({
    schemaVersion: z.literal(2),
    sessionId: SafeId,
    variantId: SafeId,
    label: z.string(),
    brief: z.string(),
    sessionPrompt: z.string(),
    projectKind: z.enum(['existing', 'fresh']),
    status: z.enum([
      'completed',
      'committed',
      'rejected',
      'cancelled',
      'removed',
    ]),
    createdAt: z.string(),
    statusChangedAt: z.string(),
    changedFilesCount: z.number().int().nonnegative(),
    artifact: z.discriminatedUnion('kind', [
      z
        .object({
          kind: z.literal('diff'),
          diffPath: z.literal('diff.patch'),
          filesPath: z.literal('files').optional(),
        })
        .passthrough(),
      z
        .object({
          kind: z.literal('project'),
          filesPath: z.literal('files'),
          runnablePath: z.string().optional(),
        })
        .passthrough(),
    ]),
    preview: z.discriminatedUnion('kind', [
      z
        .object({
          kind: z.literal('static'),
          rootPath: z.literal('files'),
          entryPath: z.string(),
        })
        .passthrough(),
      z
        .object({
          kind: z.literal('dev-server'),
          rootPath: z.literal('files'),
          command: z
            .object({
              cwd: z.string(),
              packageManager: z.string(),
              script: z.string(),
            })
            .passthrough(),
          runnablePath: z.string().optional(),
        })
        .passthrough(),
      z
        .object({
          kind: z.literal('none'),
          reason: z.enum(['diff_only', 'missing_entry', 'unsupported']),
        })
        .passthrough(),
    ]),
    tree: Pointer.extend({
      treeSha: z.string().regex(/^[a-f0-9]{40}$/),
    }).optional(),
    base: Pointer.optional(),
    parent: Pointer.optional(),
  })
  .passthrough();

export const sourceFiles = async (dataDirectory: string): Promise<string[]> => {
  const files: string[] = [];
  const walk = async (relative: string): Promise<void> => {
    const absolute = path.join(dataDirectory, relative);
    const stat = await fs.lstat(absolute);
    if (stat.isSymbolicLink())
      throw new Error(`Cannot import symbolic link: ${relative}`);
    if (relative === path.join('store.git', 'objects', 'info', 'alternates'))
      throw new Error('Snapshot store depends on an external object database');
    if (stat.isFile()) {
      files.push(relative);
      return;
    }
    if (!stat.isDirectory())
      throw new Error(`Cannot import non-regular file: ${relative}`);
    for (const name of (await fs.readdir(absolute)).sort()) {
      if (relative === 'store.git' && !SNAPSHOT_TOP_LEVEL.has(name)) continue;
      if (name.endsWith('.lock')) continue;
      await walk(path.join(relative, name));
    }
  };
  for (const name of HISTORY_DIRECTORIES) {
    if (fsSync.existsSync(path.join(dataDirectory, name))) await walk(name);
  }
  return files.sort();
};

export const sourceFingerprint = async (
  dataDirectory: string,
): Promise<string> => {
  const hash = createHash('sha256');
  for (const relative of await sourceFiles(dataDirectory)) {
    hash.update(relative);
    hash.update('\0');
    const fileHash = createHash('sha256');
    for await (const chunk of fsSync.createReadStream(
      path.join(dataDirectory, relative),
    ))
      fileHash.update(chunk);
    hash.update(fileHash.digest());
  }
  hash.update((await readSourcePresentation(dataDirectory)) ?? '');
  return hash.digest('hex');
};

export const copySourceFiles = async (
  source: string,
  destination: string,
): Promise<void> => {
  for (const relative of await sourceFiles(source)) {
    const target = path.join(destination, relative);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.copyFile(path.join(source, relative), target);
  }
};

export const readSourceManifests = async (
  dataDirectory: string,
): Promise<VariantHistoryManifest[]> => {
  const manifests: VariantHistoryManifest[] = [];
  for (const relative of await sourceFiles(dataDirectory)) {
    const parts = relative.split(path.sep);
    if (
      parts[0] !== 'variants' ||
      parts.length !== 4 ||
      parts[3] !== 'manifest.json'
    )
      continue;
    if (parts[2].includes('.tmp-')) continue;
    const raw: unknown = JSON.parse(
      await fs.readFile(path.join(dataDirectory, relative), 'utf8'),
    );
    if (
      typeof raw !== 'object' ||
      !raw ||
      !('schemaVersion' in raw) ||
      raw.schemaVersion !== 2
    )
      throw new Error(`Unsupported history schema in ${relative}`);
    const parsed = ManifestSchema.parse(raw);
    if (parsed.sessionId !== parts[1] || parsed.variantId !== parts[2])
      throw new Error(`History identity mismatch in ${relative}`);
    manifests.push(parsed);
  }
  return manifests;
};

export const verifyArtifactFile = async (
  root: string,
  relative: string,
): Promise<void> => {
  const absolute = path.resolve(root, relative);
  if (!absolute.startsWith(path.resolve(root) + path.sep))
    throw new Error('Artifact escapes its history directory');
  if (!(await fs.stat(absolute)).isFile())
    throw new Error(`Missing artifact: ${relative}`);
};

export const relocateContext = async (args: {
  sourceDirectory: string;
  stageDirectory: string;
  bundleDirectory: string;
}): Promise<void> => {
  const sourceContext = path.join(args.sourceDirectory, 'variant-context');
  const canonicalContext = fsSync.existsSync(sourceContext)
    ? fsSync.realpathSync(sourceContext)
    : sourceContext;
  const destinationContext = path.join(args.bundleDirectory, 'variant-context');
  const relocate = (value: unknown): unknown => {
    if (typeof value === 'string' && path.isAbsolute(value)) {
      let canonical = value;
      try {
        canonical = fsSync.realpathSync(value);
      } catch {
      }
      if (isPathWithinRoot(canonicalContext, canonical))
        return path.join(
          destinationContext,
          path.relative(canonicalContext, canonical),
        );
    }
    if (Array.isArray(value)) return value.map(relocate);
    if (value && typeof value === 'object')
      return Object.fromEntries(
        Object.entries(value).map(([key, nested]) => [key, relocate(nested)]),
      );
    return value;
  };
  for (const relative of await sourceFiles(args.sourceDirectory)) {
    if (
      !isPathStrictlyInsideRoot('variant-context', relative) ||
      !relative.endsWith(path.sep + 'context.json')
    )
      continue;
    const filename = path.join(args.stageDirectory, relative);
    const document: unknown = JSON.parse(await fs.readFile(filename, 'utf8'));
    await fs.writeFile(
      filename,
      JSON.stringify(relocate(document), null, 2) + '\n',
    );
  }
};
